package markdown

import (
	"bufio"
	"bytes"
	"encoding/json"
	"os"
	"sort"
	"strings"
	"testing"
)

// The corpus and its golden are the upstream-parity artifacts in the tui
// package: md_corpus.json is the Markdown input, md_golden.txt is the token
// projection generated by Marked (which upstream markdown.ts calls). The new
// renderer must reproduce that projection for every case that pier uses.

func loadGoldenCorpus(t *testing.T) map[string]string {
	t.Helper()
	data, err := os.ReadFile("../../tui/testdata/md_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := map[string]string{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}
	return corpus
}

func loadGolden(t *testing.T) map[string]string {
	t.Helper()
	file, err := os.Open("../../tui/testdata/md_golden.txt")
	if err != nil {
		t.Fatalf("open golden: %v", err)
	}
	defer file.Close()
	values := map[string]string{}
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1<<20), 1<<20)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.SplitN(line, " => ", 2)
		if len(parts) != 2 {
			t.Fatalf("bad golden line %q", line)
		}
		values[parts[0]] = parts[1]
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan: %v", err)
	}
	return values
}

// projectBlocks renders the model into Marked's token JSON (as the golden's
// stable() serialization, with sorted keys).
func projectBlocks(blocks []*Block) []any {
	out := make([]any, 0, len(blocks))
	for _, b := range blocks {
		out = append(out, projectBlock(b))
	}
	return out
}

func projectBlock(b *Block) any {
	m := map[string]any{"type": blockTypeName(b.Kind)}
	switch b.Kind {
	case BlockParagraph:
		m["text"] = b.Text
		m["tokens"] = projectInlines(b.Inlines)
	case BlockHeading:
		m["depth"] = b.Level
		m["text"] = b.Text
		m["tokens"] = projectInlines(b.Inlines)
	case BlockCode:
		if b.Info != "" {
			m["lang"] = b.Info
		}
		if b.Raw != "" {
			m["raw"] = b.Raw
		}
		if b.Body != "" {
			m["text"] = b.Body
		}
	case BlockThematicBreak:
		// type only
	case BlockQuote:
		m["text"] = b.Text
		m["tokens"] = projectBlocks(b.Blocks)
	case BlockList:
		m["items"] = projectBlocks(b.Blocks)
		if b.Ordered {
			m["ordered"] = true
			m["start"] = b.StartNumber
		}
	case BlockListItem:
		if b.Task {
			m["task"] = true
			m["checked"] = b.Checked
		}
		m["text"] = b.Text
		m["tokens"] = projectListItemTokens(b)
	case BlockTable:
		aligns := make([]any, 0, len(b.Align))
		for _, a := range b.Align {
			if a == AlignNone {
				aligns = append(aligns, nil)
			} else {
				aligns = append(aligns, a.name())
			}
		}
		m["align"] = aligns
		m["header"] = projectTableCells(b.Header, b.headerInlines, b.Align)
		rows := make([]any, 0, len(b.Rows))
		for i, row := range b.Rows {
			rows = append(rows, projectTableCells(row, b.rowInlines[i], b.Align))
		}
		if len(rows) > 0 {
			m["rows"] = rows
		}
	case BlockHTML:
		m["text"] = b.Raw
	case BlockLatex:
		m["raw"] = b.Raw
		m["text"] = b.Text
		if b.Pending {
			m["pending"] = true
		}
	case BlockSpace:
		delete(m, "type")
		m["type"] = "space"
	}
	return m
}

// projectListItemTokens projects an item's children; a tight item's paragraph
// becomes Marked's `text` token instead of a `paragraph`.
func projectListItemTokens(b *Block) []any {
	out := make([]any, 0, len(b.Blocks)+1)
	if b.Task {
		out = append(out, map[string]any{"type": "checkbox"})
	}
	for _, child := range b.Blocks {
		if child.Kind == BlockParagraph && b.Tight {
			out = append(out, map[string]any{"type": "text", "text": child.Text, "tokens": projectInlines(child.Inlines)})
			continue
		}
		out = append(out, projectBlock(child))
	}
	return out
}

func blockTypeName(k BlockKind) string {
	switch k {
	case BlockParagraph:
		return "paragraph"
	case BlockHeading:
		return "heading"
	case BlockCode:
		return "code"
	case BlockQuote:
		return "blockquote"
	case BlockList:
		return "list"
	case BlockListItem:
		return "list_item"
	case BlockThematicBreak:
		return "hr"
	case BlockTable:
		return "table"
	case BlockHTML:
		return "html"
	case BlockLatex:
		return "latexBlock"
	case BlockSpace:
		return "space"
	}
	return "unknown"
}

func projectTableCells(cells []string, inlines [][]Inline, aligns []Align) []any {
	out := make([]any, 0, len(cells))
	for i, cell := range cells {
		m := map[string]any{"text": cell, "tokens": projectInlines(inlines[i])}
		if i < len(aligns) && aligns[i] != AlignNone {
			m["align"] = aligns[i].name()
		}
		out = append(out, m)
	}
	return out
}

func projectInlines(inlines []Inline) []any {
	out := make([]any, 0, len(inlines))
	for _, in := range inlines {
		out = append(out, projectInline(in))
	}
	return out
}

func projectInline(in Inline) any {
	m := map[string]any{"type": inlineTypeName(in.Kind)}
	switch in.Kind {
	case InlineText, InlineCode, InlineHTML:
		m["text"] = in.Text
	case InlineStrong, InlineEmphasis, InlineStrikethrough:
		m["text"] = in.Text
		m["tokens"] = projectInlines(in.Children)
	case InlineLink, InlineImage:
		m["href"] = in.Dest
		if in.Title != "" {
			m["title"] = in.Title
		}
		m["text"] = in.Text
		m["tokens"] = projectInlines(in.Children)
	case InlineHardBreak:
		// type only
	case InlineEscape:
		m["raw"] = in.Raw
		m["text"] = in.Text
	case InlineLatex:
		m["raw"] = in.Raw
		m["text"] = in.Text
		if in.Pending {
			m["pending"] = true
		}
	case InlineCheckbox:
		// type only
	}
	return m
}

func inlineTypeName(k InlineKind) string {
	switch k {
	case InlineText:
		return "text"
	case InlineCode:
		return "codespan"
	case InlineStrong:
		return "strong"
	case InlineEmphasis:
		return "em"
	case InlineStrikethrough:
		return "del"
	case InlineLink:
		return "link"
	case InlineImage:
		return "image"
	case InlineHardBreak:
		return "br"
	case InlineEscape:
		return "escape"
	case InlineHTML:
		return "html"
	case InlineLatex:
		return "latex"
	case InlineCheckbox:
		return "checkbox"
	}
	return "unknown"
}

// TestMarkedGoldenParity is the differential harness: it reports every case the
// new renderer does not yet match, so the work can be driven by the corpus.
func TestMarkedGoldenParity(t *testing.T) {
	corpus := loadGoldenCorpus(t)
	golden := loadGolden(t)
	names := make([]string, 0, len(corpus))
	for name := range corpus {
		names = append(names, name)
	}
	sort.Strings(names)

	var failed []string
	for _, name := range names {
		want, ok := golden[name]
		if !ok {
			t.Fatalf("missing golden %q", name)
		}
		got := stableValue(projectBlocks(Lex(corpus[name])))
		if got != want {
			failed = append(failed, name)
		}
	}
	t.Logf("golden parity: %d/%d cases", len(names)-len(failed), len(names))
	if len(failed) > 0 {
		const show = 8
		for i, name := range failed {
			if i >= show {
				break
			}
			got := stableValue(projectBlocks(Lex(corpus[name])))
			t.Errorf("%s:\n got %s\nwant %s", name, got, golden[name])
		}
		t.Fatalf("%d cases differ: %v", len(failed), failed)
	}
}

// stableValue serializes with sorted keys, matching the JS stable() helper.
func stableValue(value any) string {
	switch typed := value.(type) {
	case nil:
		return "null"
	case string:
		return mustJSON(typed)
	case bool:
		if typed {
			return "true"
		}
		return "false"
	case int:
		return itoa(typed)
	case []any:
		parts := make([]string, 0, len(typed))
		for _, item := range typed {
			parts = append(parts, stableValue(item))
		}
		return "[" + strings.Join(parts, ",") + "]"
	case map[string]any:
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		parts := make([]string, 0, len(keys))
		for _, key := range keys {
			parts = append(parts, mustJSON(key)+":"+stableValue(typed[key]))
		}
		return "{" + strings.Join(parts, ",") + "}"
	default:
		encoded, err := json.Marshal(typed)
		if err != nil {
			panic(err)
		}
		return string(encoded)
	}
}

func mustJSON(value string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(value); err != nil {
		panic(err)
	}
	return strings.TrimRight(buf.String(), "\n")
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// The emphasis cases added for v1.4.0 b2d0da6fe were generated with marked
// 18.0.11 plus marked-cjk-friendly 0.1.2 (upstream's markdown.ts pipeline):
//
//	node -e '...' > cases   # lex tui/testdata/md_corpus.json, project tokens
//
// The projection mirrors projectBlock/projectInline above; the LaTeX extension
// and trimPartialClosingFences are pier/upstream wrapper behaviors that the
// generator does not apply, so those existing lines were kept as generated
// earlier.
func TestMarkedGoldenParityCoversCJKEmphasis(t *testing.T) {
	corpus := loadGoldenCorpus(t)
	golden := loadGolden(t)
	for _, label := range []string{
		"cjk-strong-punctuation",
		"cjk-strong-then-digit",
		"cjk-strong-quotes",
		"cjk-em-punctuation",
		"em-punctuation-then-letter",
		"em-intraword-underscore",
		"em-intraword-underscore-run",
		"em-strong-underscore-run",
		"em-strong-nested-in-strong",
		"em-strong-in-em-different-run",
		"em-mixed-run-lengths",
		"em-triple-then-single",
	} {
		source, ok := corpus[label]
		if !ok {
			t.Fatalf("%s missing from the corpus", label)
		}
		if _, ok := golden[label]; !ok {
			t.Fatalf("%s missing from the golden", label)
		}
		got := stableValue(projectBlocks(Lex(source)))
		if got != golden[label] {
			t.Fatalf("%s:\n got %s\nwant %s", label, got, golden[label])
		}
	}
}
